function modelTestEditor(id){rememberRevision('model_tests',id);const row=S.data.model_tests.find(r=>r.id===id)||{},fields=[['name','测试名称'],['model_name','模型名称'],['model_version','模型版本'],['test_date','测试日期'],['light_source','光源类型'],['camera','相机型号'],['lens','镜头型号']];const d=extraDialog(`<form><div class="dialogtop"><h2>${id?'编辑':'新增'}大模型测试记录</h2><button type="button" data-close>✕</button></div>${fields.map(([name,label])=>`<label>${label}<input name="${name}" value="${esc(row[name])}" ${['name','model_name'].includes(name)?'required':''} ${name==='test_date'?'type="date"':''}></label>`).join('')}<label>关联产品<select name="product_id"><option value="">暂不关联</option>${S.data.products.map(p=>`<option value="${p.id}" ${p.id===row.product_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>工作距离（mm）<input name="working_distance_mm" type="number" min="0" step="any" value="${row.working_distance_mm??''}" placeholder="例如 120.5"></label><label>产品规格<textarea name="product_spec" maxlength="1024">${esc(row.product_spec)}</textarea></label><label>测试产品总数<input name="test_count" type="number" min="0" step="1" value="${row.test_count??''}"></label><label>检出率（%）<input name="detection_rate" type="number" min="0" max="100" step="any" value="${row.detection_rate??''}" placeholder="例如 98.5"></label><label>良率（%）<input name="yield_rate" type="number" min="0" max="100" step="any" value="${row.yield_rate??''}" placeholder="例如 1.5"></label><label>测试环境备注<textarea name="prompt" maxlength="1024">${esc(row.prompt)}</textarea></label><label>效果说明<textarea name="remark" maxlength="1024">${esc(row.remark)}</textarea></label><p>先保存记录，再上传测试原图和效果图。</p><p class="error"></p><button class="primary">保存测试记录</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const j=await request('/api/save',{table:'model_tests',id,record:Object.fromEntries(new FormData(e.target))});d.close();await refresh();if(!id)modelTestUpload(j.id)}catch(e){d.querySelector('.error').textContent=e.message}}}
function modeltests(){const records=[...S.data.model_tests].sort((a,b)=>b.id-a.id);$('#content').innerHTML=title('MODEL TEST LOG','大模型测试记录','记录模型、测试产品、检出率与良率，点击图片放大查看。',S.auth?'<button class="primary" id="new-model-test">＋ 新增测试记录</button>':'<span class="pill">只读浏览</span>')+'<button id="offline-shortcut">进入大模型离线测试 →</button><input id="model-test-filter" class="search" placeholder="搜索测试名称、模型、产品、相机、光源、规格…"><div id="model-test-list"></div>';$('#offline-shortcut').onclick=()=>go('offline');$('#new-model-test')?.addEventListener('click',()=>modelTestEditor());const draw=()=>{const q=$('#model-test-filter').value.trim().toLowerCase(),all=records.filter(r=>[r.name,r.model_name,r.model_version,r.remark,r.prompt,r.light_source,r.camera,r.lens,r.product_spec,r.working_distance_mm,label('products',r.product_id)].join(' ').toLowerCase().includes(q));$('#model-test-list').innerHTML=all.map(r=>{const files=S.data.model_test_files.filter(f=>f.test_id===r.id);return `<section class="panel model-test-panel"><div class="panelhead"><h2>${esc(r.name)}</h2><span class="pill">${r.test_count??'待填'} 个测试产品</span></div><p>模型：${esc(r.model_name)} ${esc(r.model_version)} · ${esc(r.test_date||'未填写日期')} · 产品：${esc(r.product_id?label('products',r.product_id):'未关联')}</p><div class="model-hardware"><p>光源类型：${esc(r.light_source||'未填写')} · 相机：${esc(r.camera||'未填写')} · 镜头：${esc(r.lens||'未填写')}</p><p>工作距离：${r.working_distance_mm==null?'未填写':esc(r.working_distance_mm)+' mm'}</p><p class="model-test-note">产品规格：${esc(r.product_spec||'未填写')}</p></div><p>检出率：${r.detection_rate==null?'待填写':esc(r.detection_rate)+'%'} · 良率：${r.yield_rate==null?'待填写':esc(r.yield_rate)+'%'}</p><p class="subtle">录入作者：${esc(r.created_by||'历史记录未登记')} · ${esc(r.created_at||'')}</p><p class="model-test-note">${esc(r.remark||'尚未填写效果说明')}</p><details><summary>测试环境备注</summary><p class="model-test-note">${esc(r.prompt||'未填写')}</p></details>${['input','result'].map(role=>`<h3>${role==='input'?'测试原图':'检测效果图'}</h3><div class="model-test-gallery">${files.filter(f=>f.role===role).map(f=>{const asset=S.data.assets.find(a=>a.id===f.asset_id);return `<figure><button type="button" class="model-preview-button" data-model-preview="${f.asset_id}"><img loading="lazy" src="/api/media?id=${f.asset_id}&mode=thumb" alt="${esc(asset?.file_name)}"></button><figcaption>${esc(asset?.file_name)}<small class="subtle"> 上传作者：${esc(asset?.created_by||'历史记录未登记')}</small> <a href="/api/media?id=${f.asset_id}&mode=original">下载原图</a>${S.auth?` <button data-model-file-rename="${f.id}">重命名</button>`:''}${S.auth?.role==='admin'?` <button class="danger" data-model-file-delete="${f.id}">删除图片</button>`:''}</figcaption></figure>`}).join('')||'<p class="muted">暂无图片</p>'}</div>`).join('')}<div class="toolbar">${S.auth?`<button data-model-edit="${r.id}">编辑记录</button><button data-model-upload="${r.id}">上传 / 粘贴图片</button>`:''}${S.auth?.role==='admin'?`<button class="danger" data-model-delete="${r.id}">删除测试记录</button>`:''}</div></section>`}).join('')||'<div class="empty">暂无测试记录</div>';$('#model-test-list').querySelectorAll('[data-model-file-rename]').forEach(b=>b.onclick=()=>renameModelTestImage(Number(b.dataset.modelFileRename)));$('#model-test-list').querySelectorAll('[data-model-file-delete]').forEach(b=>b.onclick=()=>deleteModelTestImage(Number(b.dataset.modelFileDelete)));$('#model-test-list').querySelectorAll('[data-model-preview]').forEach(b=>b.onclick=()=>modelImagePreview(Number(b.dataset.modelPreview)));$('#model-test-list').querySelectorAll('[data-model-edit]').forEach(b=>b.onclick=()=>modelTestEditor(Number(b.dataset.modelEdit)));$('#model-test-list').querySelectorAll('[data-model-upload]').forEach(b=>b.onclick=()=>modelTestUpload(Number(b.dataset.modelUpload)));$('#model-test-list').querySelectorAll('[data-model-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('删除测试记录及其图片关联？原文件保留在备份目录中。'))return;try{await request('/api/model-test-delete',{id:Number(b.dataset.modelDelete)});await refresh()}catch(e){toast(e.message)}})};$('#model-test-filter').oninput=draw;draw()}
function modelTestUpload(id){const d=extraDialog(`<div class="dialogtop"><h2>添加测试图片</h2><button data-close>✕</button></div><label>图片用途<select data-role><option value="input">测试原图</option><option value="result">检测效果图</option></select></label><div class="uploadbox" tabindex="0" data-test-drop><p>选择或拖拽图片，也可在此窗口按 Ctrl+V 粘贴截图</p><input data-test-files type="file" accept="image/png,image/jpeg,image/bmp,image/tiff,image/webp" multiple></div><p data-test-status role="status"></p>`);let busy=false;async function upload(files){if(busy||!files.length)return;busy=true;const role=d.querySelector('[data-role]').value,status=d.querySelector('[data-test-status]');d.querySelector('[data-role]').disabled=true;let count=0;try{for(const file of files){if(file.size>256*1024*1024)throw Error(file.name+' 超过 256 MB');const q=new URLSearchParams({kind:'modeltest',test_id:id,role,name:file.name||'clipboard.png'}),r=await fetch('/api/upload?'+q,{method:'POST',headers:{'X-AOI-Client':'local-v1'},body:file}),j=await r.json();if(!r.ok)throw Error(j.error);count++}status.textContent=`成功保存 ${count} 张${role==='input'?'测试原图':'效果图'}，可切换用途继续添加。`;S=await request('/api/state')}catch(e){status.textContent=`已保存 ${count} 张；${e.message}`}finally{busy=false;d.querySelector('[data-role]').disabled=false}}d.querySelector('[data-test-files]').onchange=e=>{upload(Array.from(e.target.files));e.target.value=''};const zone=d.querySelector('[data-test-drop]');zone.ondragover=e=>e.preventDefault();zone.ondrop=e=>{e.preventDefault();upload(Array.from(e.dataTransfer.files))};d.addEventListener('paste',e=>{const files=Array.from(e.clipboardData.items).filter(i=>i.type.startsWith('image/')).map(i=>i.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();upload(files)}});d.addEventListener('close',()=>refresh(),{once:true})}

